import React, { useState } from 'react';
import { Eye, EyeOff, CheckCircle, XCircle, AlertCircle } from 'lucide-react';

const InputField = ({
  label,
  type = 'text',
  name,
  value,
  onChange,
  placeholder,
  error,
  success,
  icon: Icon,
  required = false,
  className = '',
  validationRules = [],
  showStrength = false,
}) => {
  const [showPassword, setShowPassword] = useState(false);
  const [isFocused, setIsFocused] = useState(false);

  const isPassword = type === 'password';
  const inputType = isPassword && showPassword ? 'text' : type;

  // Validation de la force du mot de passe
  const getPasswordStrength = (password) => {
    if (!password) return { score: 0, label: '', color: '' };

    let score = 0;
    if (password.length >= 8) score++;
    if (/[A-Z]/.test(password)) score++;
    if (/[0-9]/.test(password)) score++;
    if (/[^A-Za-z0-9]/.test(password)) score++;

    const strengths = [
      { label: 'Très faible', color: 'bg-red-500' },
      { label: 'Faible', color: 'bg-orange-500' },
      { label: 'Moyen', color: 'bg-yellow-500' },
      { label: 'Fort', color: 'bg-green-500' },
      { label: 'Très fort', color: 'bg-emerald-600' },
    ];

    return strengths[Math.min(score, strengths.length - 1)];
  };

  const passwordStrength = isPassword && showStrength ? getPasswordStrength(value) : null;

  return (
    <div className={`mb-6 ${className}`}>
      <div className="flex justify-between items-center mb-2">
        <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300">
          {label} {required && <span className="text-red-500">*</span>}
        </label>
        {isPassword && showStrength && value && (
          <span className={`text-xs font-semibold px-2 py-1 rounded-full ${passwordStrength.color.replace('bg-', 'bg-')} text-white`}>
            {passwordStrength.label}
          </span>
        )}
      </div>

      <div className={`relative ${isFocused ? 'ring-2 ring-primary-500/30' : ''} rounded-lg transition-all duration-200`}>
        {Icon && (
          <div className="absolute left-3 top-1/2 transform -translate-y-1/2">
            <Icon size={20} className="text-neutral-400" />
          </div>
        )}

        <input
          type={inputType}
          name={name}
          value={value}
          onChange={onChange}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          placeholder={placeholder}
          className={`
            w-full px-4 py-3.5 rounded-lg border
            ${Icon ? 'pl-11' : 'pl-4'}
            ${isPassword ? 'pr-12' : 'pr-4'}
            ${error 
              ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
              : success 
                ? 'border-green-300 dark:border-green-700 bg-green-50 dark:bg-green-900/20'
                : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
            }
            text-neutral-900 dark:text-white
            placeholder-neutral-500 dark:placeholder-neutral-400
            focus:outline-none focus:ring-2 focus:ring-primary-500/50
            transition-all duration-200
          `}
        />

        {isPassword && value && (
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1 text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300"
          >
            {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
          </button>
        )}

        {!isPassword && success && (
          <div className="absolute right-3 top-1/2 transform -translate-y-1/2">
            <CheckCircle size={20} className="text-green-500" />
          </div>
        )}
      </div>

      {error && (
        <div className="flex items-center mt-2 text-red-600 dark:text-red-400">
          <AlertCircle size={16} className="mr-1" />
          <span className="text-sm">{error}</span>
        </div>
      )}

      {validationRules.length > 0 && (
        <div className="mt-2 space-y-1">
          {validationRules.map((rule, index) => (
            <div key={index} className="flex items-center text-xs">
              {rule.condition ? (
                <CheckCircle size={12} className="text-green-500 mr-2" />
              ) : (
                <XCircle size={12} className="text-neutral-400 mr-2" />
              )}
              <span className={rule.condition ? 'text-green-600 dark:text-green-400' : 'text-neutral-500'}>
                {rule.text}
              </span>
            </div>
          ))}
        </div>
      )}

      {isPassword && showStrength && value && (
        <div className="mt-2">
          <div className="h-1.5 w-full bg-neutral-200 dark:bg-neutral-700 rounded-full overflow-hidden">
            <div 
              className={`h-full ${passwordStrength.color} transition-all duration-300`}
              style={{ width: `${((passwordStrength.score + 1) / 5) * 100}%` }}
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default InputField;
